import java.util.*;

public class Main {
    // Scales a decimal with at most 8 fractional digits to an exact integer count of 1e-8 units.
    static long scaled(String s) {
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot), frac = dot < 0 ? "" : s.substring(dot + 1);
        frac = (frac + "00000000").substring(0, 8);
        return Long.parseLong(whole) * 100000000L + Long.parseLong(frac);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String a = sc.next(), b = sc.next();
        System.out.println((scaled(a) + scaled(b)) / 100000000L);
    }
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

// scaled turns a decimal with at most 8 fractional digits into an exact count of 1e-8 units.
func scaled(s string) int64 {
	whole, frac, _ := strings.Cut(s, ".")
	frac = (frac + "00000000")[:8]
	w, _ := strconv.ParseInt(whole, 10, 64)
	f, _ := strconv.ParseInt(frac, 10, 64)
	return w*100000000 + f
}

func main() {
	var a, b string
	fmt.Scan(&a, &b)
	fmt.Println((scaled(a) + scaled(b)) / 100000000)
}
